DEADLINE_DAYS  = {'DISCLOSE NOW': 30, 'DISCLOSE WITHIN 60 DAYS': 60, 'DISCLOSE WITHIN 90 DAYS': 90}
DECISION_ORDER = {
    'DISCLOSE NOW': 0, 'DISCLOSE WITHIN 60 DAYS': 1, 'DISCLOSE WITHIN 90 DAYS': 2,
    'MONITOR': 3, 'ALREADY PUBLIC': 4, 'MANUAL REVIEW': 5,
}

_COMPLEX = {'low': 2.0, 'medium': 0.0, 'high': -2.0}
_IMPACT  = {'safety hazard': 3.0, 'process halt': 2.0, 'service disruption': 1.0, 'none': 0.0}
_EXPOSE  = {'internet': 2.0, 'internal network': 1.0, 'vpn only': 0.0, 'serial port': -1.0}

# ICS-specific object_relations that distinguish our research objects
# from vulnerability objects added by the MISP cve enrichment module
_ICS_FIELDS = {'exploit-complexity', 'operational-impact', 'exposure', 'poc-available'}


def http_get(url, timeout=12):
    try:
        req = urllib.request.Request(url, headers={'Accept': 'application/json', 'User-Agent': 'misp-otics-lab/1.0'})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read()), None
    except urllib.error.HTTPError as e:
        return {}, 'HTTP ' + str(e.code)
    except Exception as e:
        return {}, str(e)


def http_get_auth(url, key, timeout=15):
    try:
        req = urllib.request.Request(url, headers={'Authorization': key, 'Accept': 'application/json'})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read()), None
    except urllib.error.HTTPError as e:
        return {}, 'HTTP ' + str(e.code)
    except Exception as e:
        return {}, str(e)


def http_post(url, body, extra_headers=None, timeout=15):
    try:
        data = json.dumps(body).encode()
        h = {'Content-Type': 'application/json', 'Accept': 'application/json'}
        if extra_headers:
            h.update(extra_headers)
        req = urllib.request.Request(url, data=data, headers=h, method='POST')
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read()), None
    except urllib.error.HTTPError as e:
        snippet = ''
        try:
            snippet = e.read().decode()[:160]
        except Exception:
            pass
        return {}, 'HTTP ' + str(e.code) + ': ' + snippet
    except Exception as e:
        return {}, str(e)


def _auth(key):
    return {'Authorization': key}


def add_attr(eid, atype, value, category, url, key):
    if value in (None, '', 0):
        return None
    _, err = http_post(
        url + '/attributes/add/' + eid,
        {'Attribute': {'type': atype, 'category': category, 'value': str(value)}},
        extra_headers=_auth(key),
    )
    return err


def to_float(v):
    if v is None:
        return None
    try:
        return float(v)
    except (ValueError, TypeError):
        return None


def fetch_kev():
    d, _ = http_get(
        'https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json',
        timeout=20,
    )
    return {v['cveID'] for v in d.get('vulnerabilities', [])}


def fetch_epss(cve_id):
    d, _ = http_get('https://api.first.org/data/v1/epss?cve=' + cve_id)
    entries = d.get('data', [])
    if entries:
        try:
            return float(entries[0].get('epss', 0))
        except (ValueError, TypeError):
            pass
    return 0.0


def ics_score(ctx, kev=False, epss=0.0):
    s = float(ctx.get('cvss_score') or 0)
    s += _COMPLEX.get((ctx.get('exploit_complexity') or '').lower(), 0)
    s += _IMPACT.get((ctx.get('operational_impact') or '').lower(), 0)
    s += _EXPOSE.get((ctx.get('exposure') or '').lower(), 0)
    if ctx.get('poc_available'):
        s += 1.0
    if kev:
        s += 2.0
    if epss > 0.5:
        s += 1.0
    return round(s, 1)


def triage_decision(score, status):
    if (status or '').lower() == 'public':
        return 'ALREADY PUBLIC'
    if score >= 9:  return 'DISCLOSE NOW'
    if score >= 7:  return 'DISCLOSE WITHIN 60 DAYS'
    if score >= 4:  return 'DISCLOSE WITHIN 90 DAYS'
    if score > 0:   return 'MONITOR'
    return 'MANUAL REVIEW'


def lookup_psirt(vendor):
    vl = (vendor or '').lower()
    for k, v in EU_PSIRTS.items():
        if k in vl:
            return v
    return {'name': vendor + ' Security Team',
            'email': 'security@' + vl.replace(' ', '') + '.com',
            'nat_cert': 'ENISA'}


def parse_software_object(event_data):
    """Extract vendor/product/version from the software object in the event."""
    for obj in event_data.get('Event', {}).get('Object', []):
        if obj.get('name') == 'software':
            attrs = {a.get('object_relation'): a.get('value') for a in obj.get('Attribute', [])}
            return {
                'vendor':  attrs.get('vendor', ''),
                'product': attrs.get('name', ''),
                'version': attrs.get('version', ''),
            }
    return {'vendor': '', 'product': '', 'version': ''}


def parse_vuln_objects(event_data):
    """Return list of research vulnerability dicts from the event's vulnerability objects.

    Research objects are distinguished from enrichment-added objects by the
    presence of ICS-specific object_relation values (exploit-complexity,
    operational-impact, exposure, poc-available) stored with force=1 during import.
    """
    vulns = []
    for obj in event_data.get('Event', {}).get('Object', []):
        if obj.get('name') != 'vulnerability':
            continue
        attrs = {a.get('object_relation'): a.get('value')
                 for a in obj.get('Attribute', [])}
        # Skip enrichment-added objects that lack our ICS scoring fields
        if not any(attrs.get(f) for f in _ICS_FIELDS):
            continue
        rid = attrs.get('id', '')
        if not rid:
            continue
        cve_str = attrs.get('cve', '') or ''
        vulns.append({
            'research_id':        rid,
            'cve':                cve_str if cve_str else None,
            'title':              attrs.get('summary', ''),
            'description':        attrs.get('description', ''),
            'cvss_score':         to_float(attrs.get('cvss-score')),
            'cwe':                attrs.get('cwe', ''),
            'disclosure_status':  attrs.get('state', 'private'),
            'exploit_complexity': attrs.get('exploit-complexity', ''),
            'operational_impact': attrs.get('operational-impact', ''),
            'exposure':           attrs.get('exposure', ''),
            'poc_available':      (attrs.get('poc-available') or '').lower() == 'true',
        })
    return vulns


def get_enriched_cvss(cve_id, event_data):
    """Return CVSS score from any vulnerability object that has one for this CVE."""
    for obj in event_data.get('Event', {}).get('Object', []):
        if obj.get('name') != 'vulnerability':
            continue
        attrs = {a.get('object_relation'): a.get('value')
                 for a in obj.get('Attribute', []) if a.get('value')}
        obj_cve = attrs.get('cve', '') or attrs.get('id', '')
        if cve_id.upper() not in (obj_cve or '').upper():
            continue
        cvss_raw = attrs.get('cvss-score')
        if cvss_raw:
            try:
                return float(cvss_raw)
            except (ValueError, TypeError):
                pass
    return None


def get_cwes_from_event(event_data):
    """Collect CWE IDs from weakness objects added by CVE enrichment."""
    cwes = []
    for obj in event_data.get('Event', {}).get('Object', []):
        if obj.get('name') == 'weakness':
            for attr in obj.get('Attribute', []):
                if attr.get('object_relation') == 'id' and attr.get('value'):
                    cwes.append(attr['value'])
    return cwes


def build_draft(vuln, fw_info, psirt, nat_cert, dl_date):
    vid        = vuln.get('research_id') or vuln.get('cve') or 'UNKNOWN'
    vendor     = fw_info.get('vendor', '')
    product    = fw_info.get('product', '')
    version    = fw_info.get('version', '')
    title      = vuln.get('title', '')
    cvss_str   = str(vuln.get('cvss_score')) if vuln.get('cvss_score') is not None else 'n/a'
    cwe_str    = vuln.get('cwe') or 'n/a'
    impact_str = vuln.get('operational_impact') or 'n/a'
    desc_str   = vuln.get('description') or ''
    nat_name   = nat_cert['name']
    nat_email  = nat_cert['email']
    vde_name   = VDE_CERT['name']
    vde_email  = VDE_CERT['email']
    nl = chr(10)
    lines = [
        'Subject: Responsible Disclosure -- ' + vid + ': ' + title + ' in ' + vendor + ' ' + product + ' ' + version,
        '',
        'Dear ' + psirt['name'] + ',',
        '',
        'We are reporting a vulnerability under the ENISA CVD framework:',
        '  ' + ENISA_CVD,
        '',
        '  ID:          ' + vid,
        '  Title:       ' + title,
        '  Product:     ' + vendor + ' ' + product + ' ' + version,
        '  CVSS score:  ' + cvss_str,
        '  CWE:         ' + cwe_str,
        '  Impact:      ' + impact_str,
        '',
        '  Description: ' + desc_str,
        '',
        '  Disclosure deadline:  ' + str(dl_date),
        '  National CERT CC:     ' + nat_name + ' <' + nat_email + '>',
        '  ICS coordinator CC:   ' + vde_name + ' <' + vde_email + '>',
        '',
        'Regards,',
        'ICS Firmware Research Lab',
    ]
    return nl.join(lines)


def run_triage(misp_url, misp_key):
    today  = datetime.now(timezone.utc).replace(tzinfo=None)
    errors = []

    kev_ids = fetch_kev()

    # Query all Firmware research events in MISP
    r, err = http_post(
        misp_url + '/events/restSearch',
        {'returnFormat': 'json', 'searchinfo': 'Firmware research --', 'limit': 200},
        extra_headers=_auth(misp_key),
    )
    if err:
        errors.append('restSearch: ' + err)
        return json.dumps({'success': False, 'errors': errors})

    events = r.get('response', [])
    if not events:
        return json.dumps({'success': True,
                           'message': 'No Firmware research events found in MISP',
                           'total': 0, 'vulnerabilities': []})

    rankings = []

    for event_wrapper in events:
        event = event_wrapper if 'id' in event_wrapper else event_wrapper.get('Event', {})
        eid   = str(event.get('id', ''))
        label = (event.get('info') or '').replace('Firmware research -- ', '')
        if not eid:
            continue

        # Fetch full event with all objects and attributes
        full, err = http_get_auth(misp_url + '/events/' + eid, misp_key)
        if err:
            errors.append('get_event(' + eid + '): ' + err)
            continue

        fw_info = parse_software_object(full)
        vulns   = parse_vuln_objects(full)
        cwes    = get_cwes_from_event(full)

        if not vulns:
            errors.append('event ' + eid + ' (' + label + '): no research vulnerability objects found -- import with OT/ICS Firmware Findings Import first')
            continue

        fw_summaries = []
        nl2 = chr(10) + chr(10)

        for vuln in vulns:
            rid    = vuln['research_id']
            cve_id = vuln['cve']

            # Use CVSS from the vulnerability object; fall back to enriched CVSS
            cvss = vuln['cvss_score']
            if not cvss and cve_id:
                enriched = get_enriched_cvss(cve_id, full)
                if enriched:
                    cvss = enriched
                    vuln = dict(vuln, cvss_score=cvss)

            kev  = (cve_id in kev_ids) if cve_id else False
            epss = fetch_epss(cve_id) if cve_id else 0.0

            score    = ics_score(vuln, kev=kev, epss=epss)
            decision = triage_decision(score, vuln['disclosure_status'])
            dl_days  = DEADLINE_DAYS.get(decision)
            dl_date  = (today + timedelta(days=dl_days)).strftime('%Y-%m-%d') if dl_days else None

            vendor       = fw_info.get('vendor') or label.split()[0] if label.split() else label
            psirt        = lookup_psirt(vendor)
            nat_cert_key = psirt.get('nat_cert', 'ENISA')
            nat_cert     = EU_NAT_CERTS.get(nat_cert_key, EU_NAT_CERTS['ENISA'])
            draft        = build_draft(vuln, fw_info, psirt, nat_cert, dl_date) if dl_date else ''

            title      = vuln['title'] or rid
            cvss_str   = str(cvss) if cvss is not None else 'n/a'
            cwe_str    = vuln['cwe'] or ', '.join(cwes) or 'n/a'
            impact_str = vuln['operational_impact'] or 'n/a'
            expose_str = vuln['exposure'] or 'n/a'
            kev_str    = 'YES -- actively exploited in the wild' if kev else 'no'
            epss_val   = '{:.3f}'.format(epss)
            epss_tag   = ' [>50% exploitation probability]' if epss > 0.5 else ''

            summary_lines = [
                '  [' + decision + ']  ' + rid,
                '    Title:    ' + title,
                '    CVSS:     ' + cvss_str,
                '    CWE:      ' + cwe_str,
                '    KEV:      ' + kev_str,
                '    EPSS:     ' + epss_val + epss_tag,
                '    Impact:   ' + impact_str,
                '    Exposure: ' + expose_str,
                '    Score:    ' + str(score),
            ]
            fw_summaries.append(chr(10).join(summary_lines))

            rankings.append({
                'rank':               0,
                'triage_score':       score,
                'triage_decision':    decision,
                'research_id':        rid,
                'cve':                cve_id,
                'title':              title,
                'cvss_score':         cvss,
                'kev':                kev,
                'epss':               epss,
                'cwes_enriched':      cwes,
                'operational_impact': vuln['operational_impact'],
                'poc_available':      vuln['poc_available'],
                'disclosure_status':  vuln['disclosure_status'],
                'firmware':           label,
                'misp_event_id':      eid,
                'disclosure': {
                    'deadline_date': dl_date,
                    'vendor_psirt':  psirt,
                    'national_cert': nat_cert,
                    'draft_body':    draft,
                } if draft else None,
            })

        if fw_summaries:
            comment = '=== Triage summary: ' + label + ' ===' + nl2 + nl2.join(fw_summaries)
            err = add_attr(eid, 'comment', comment, 'Other', misp_url, misp_key)
            if err:
                errors.append('comment(' + label + '): ' + err)

    rankings.sort(key=lambda x: (DECISION_ORDER.get(x['triage_decision'], 9), -x['triage_score']))
    for i, rec in enumerate(rankings, 1):
        rec['rank'] = i

    return json.dumps({
        'success':         True,
        'total':           len(rankings),
        'events_triaged':  len(events),
        'error_count':     len(errors),
        'errors':          errors,
        'vulnerabilities': rankings,
    }, indent=2)


print(run_triage('$MISP_URL', '$MISP_API_KEY'))
